"""Engine-mixer sound bank + graph-propagated positional audio.

The mixing/output lives in necore.AudioMixer (cpal — the platform layer,
pygame's replacement); this module owns file IO, the name->id bank, and
the game's positional model. Sounds are loaded lazily from
game/assets/sfx/*.wav. A missing wav logs once to stderr and is skipped
-- the sound bank is generated by a parallel tool (tools/soundgen) and
may be partial; the game must still run silently for whatever hasn't
landed yet. A missing/failed audio DEVICE degrades to silent the same
way the old pygame.mixer.init failure did.

`EngineSound`/`EngineChannel` at the bottom are the music system's
binding surface: the exact subset of the old pygame.mixer channel model
music.py consumes (play/gapless queue/get_queue/set_volume/stop/
fadeout/get_busy), backed by the engine mixer.
"""

from __future__ import annotations

import sys
import wave as wavemod
from pathlib import Path

import numpy as np

import necore

SFX_DIR = Path(__file__).resolve().parents[1] / "assets" / "sfx"

# Sound level falls off one "stop" per portal hop away from the player, per
# the level design's audio-before-visibility horror pacing (ENGINE_DESIGN
# §3.4 / research_design.md #15).
HOP_ATTENUATION = 0.55

# engine channel ids: 0..63 belong to the music system (lanes, risers,
# tails — music.py's numbering used pygame channel indices and keeps
# them); the loops the audio system itself owns live far above
_CH_AMBIENCE = 1000
_CH_HEARTBEAT = 1001


def _wav_to_f32_stereo(path: Path) -> bytes | None:
    """Decode a wav file to interleaved stereo f32 LE bytes at 44100 Hz.
    The bank is generated at 44100/16-bit (mkvideo asserts the same);
    mono duplicates to both ears."""
    with wavemod.open(str(path)) as w:
        if w.getframerate() != 44100 or w.getsampwidth() != 2:
            print(f"[audio] {path.name}: expected 44100 Hz 16-bit, got "
                  f"{w.getframerate()}/{w.getsampwidth() * 8}bit — skipping",
                  file=sys.stderr)
            return None
        raw = np.frombuffer(w.readframes(w.getnframes()), dtype=np.int16)
        if w.getnchannels() == 2:
            st = raw.reshape(-1, 2)
        else:
            st = np.repeat(raw[:, None], 2, axis=1)
    return (st.astype(np.float32) / 32768.0).tobytes()


class _Bank:
    """name/array -> engine sound id registry. One mixer per process is
    plenty; music and sfx share it so the master mix stays coherent."""

    def __init__(self, mixer):
        self.mixer = mixer
        self._next_id = 1
        self.by_name: dict[str, int | None] = {}

    def alloc(self) -> int:
        i = self._next_id
        self._next_id += 1
        return i


class Audio:
    def __init__(self, mute: bool = False):
        self.master_vol = 1.0
        self.sfx_vol = 1.0
        self.ambience_vol = 0.35
        self.muted = mute
        # optional recorder callback (kind, name, vol, pan); fires even when
        # muted or the mixer failed, so headless captures still log audio
        self.tap = None

        self._missing_logged: set[str] = set()
        self._ambience_name: str | None = None
        self._ambience_on = False
        self._ambience_duck = 1.0  # reveal grammar: the corrupted reveal dips it
        self._heartbeat_active = False

        self._ready = False
        self.mixer = None
        self.bank: _Bank | None = None
        if not mute:
            try:
                self.mixer = necore.AudioMixer()
                self._ready = bool(self.mixer.ready)
            except Exception as exc:  # no device / backend failure
                print(f"[audio] mixer init failed, running silent: {exc}",
                      file=sys.stderr)
                self._ready = False
            if not self._ready:
                self.mixer = None
        if self.mixer is not None:
            self.bank = _Bank(self.mixer)

    # ------------------------------------------------------------------

    def _load(self, name: str) -> int | None:
        """Engine sound id for `name`, loading the wav on first use."""
        if self.bank is None:
            return None
        if name in self.bank.by_name:
            return self.bank.by_name[name]
        sid = None
        path = SFX_DIR / f"{name}.wav"
        if path.exists():
            try:
                data = _wav_to_f32_stereo(path)
                if data is not None:
                    sid = self.bank.alloc()
                    self.mixer.load_sound(sid, data)
            except Exception as exc:
                if name not in self._missing_logged:
                    print(f"[audio] failed to load {name}.wav: {exc}",
                          file=sys.stderr)
                    self._missing_logged.add(name)
                sid = None
        elif name not in self._missing_logged:
            print(f"[audio] missing sfx: {name}.wav (skipping)", file=sys.stderr)
            self._missing_logged.add(name)
        self.bank.by_name[name] = sid
        return sid

    def play(self, name: str, vol: float = 1.0, pan: float = 0.5) -> None:
        if self.tap is not None:
            self.tap("sfx", name, vol, pan)
        if self.muted or not self._ready:
            return
        sid = self._load(name)
        if sid is None:
            return
        v = max(0.0, min(1.0, vol)) * self.sfx_vol * self.master_vol
        pan = max(0.0, min(1.0, pan))
        self.mixer.sfx_play(sid, (1.0 - pan) * v, pan * v)

    # ------------------------------------------------------------------

    def handle_sounds(self, session, sounds, visible_instances=None) -> None:
        """Consume ("sound", name, polygon, x, y, vol) fx entries.

        `visible_instances` is the same list `Renderer.draw` consumes from
        `session.visible(...)`; pass it to get accurate stereo pan for
        sources currently on screen. Polygons not in that list (or when it is
        omitted) pan center -- correct for the horror-pacing case of
        hearing something before you can see it.
        """
        if not sounds:
            return
        ppolygon = session.player_polygon()
        visible_polygons: dict[int, tuple] = {}
        if visible_instances:
            for polygon, xform, depth, clip_screen, walls, entry_edge, ents in visible_instances:
                visible_polygons.setdefault(polygon, xform)
        for ev in sounds:
            if ev[0] != "sound":
                continue
            _, name, polygon, x, y, vol = ev
            hops = session.sim.hop_distance(polygon, ppolygon)
            if hops < 0:
                continue
            v = vol * (HOP_ATTENUATION ** hops)
            pan = 0.5
            xform = visible_polygons.get(polygon)
            if xform is not None:
                sx, _sy = necore.mat_apply(xform, x, y)
                w = max(1.0, float(session.screen_w))
                pan = max(0.0, min(1.0, sx / w))
            self.play(name, v, pan)

    # ------------------------------------------------------------------

    def _amb_vol(self) -> float:
        return self.ambience_vol * self.master_vol * self._ambience_duck

    def ambience(self, name: str) -> None:
        if self._ambience_name == name:
            return
        self._ambience_name = name
        if self.tap is not None:
            self.tap("ambience", name, self.ambience_vol, 0.5)
        if self._ambience_on and self.mixer is not None:
            self.mixer.ch_stop(_CH_AMBIENCE)
            self._ambience_on = False
        if self.muted or not self._ready or not name:
            return
        sid = self._load(name)
        if sid is None:
            return
        self.mixer.ch_play(_CH_AMBIENCE, sid, -1)
        v = self._amb_vol()
        self.mixer.ch_set_volume(_CH_AMBIENCE, v, v)
        self._ambience_on = True

    def duck_ambience(self, frac: float) -> None:
        """Scale the running ambience loop (1.0 = normal). The corrupted
        expansion reveal dips the polygon while the bloom sours."""
        self._ambience_duck = max(0.0, min(1.0, frac))
        if self._ambience_on and self.mixer is not None:
            v = self._amb_vol()
            self.mixer.ch_set_volume(_CH_AMBIENCE, v, v)

    def update_heartbeat(self, session) -> None:
        want = session.hp < 30 and not session.dead
        if want == self._heartbeat_active:
            return
        self._heartbeat_active = want
        if self.tap is not None:
            self.tap("heartbeat_on" if want else "heartbeat_off",
                     "heartbeat", 0.5, 0.5)
        if want:
            if self.muted or not self._ready:
                return
            sid = self._load("heartbeat")
            if sid is None:
                return
            self.mixer.ch_play(_CH_HEARTBEAT, sid, -1)
            v = 0.5 * self.master_vol
            self.mixer.ch_set_volume(_CH_HEARTBEAT, v, v)
        elif self.mixer is not None:
            self.mixer.ch_stop(_CH_HEARTBEAT)

    # ------------------------------------------------------------------

    def set_master(self, v: float) -> None:
        self.master_vol = max(0.0, min(1.0, v))

    def set_mute(self, muted: bool) -> None:
        self.muted = muted
        if muted and self.mixer is not None:
            self.mixer.stop_all()


# ---------------------------------------------------------------------------
# the music system's binding surface (pygame.mixer channel model, engine-
# backed). music.py's numbering/idiom survives; only the backend changed.
# ---------------------------------------------------------------------------

class EngineSound:
    """A registered engine sound. Built from a file path or an int16
    (N, 2) numpy array (the old sndarray.make_sound input)."""

    __slots__ = ("audio", "sid", "_frames")

    def __init__(self, audio: Audio, sid: int | None, frames: int):
        self.audio = audio
        self.sid = sid
        self._frames = frames

    def get_length(self) -> float:
        return self._frames / 44100.0

    @staticmethod
    def from_array(audio, seg: "np.ndarray") -> "EngineSound":
        # duck-typed on the audio object (tests drive the music system
        # with a stub namespace): no bank -> a silent handle
        if getattr(audio, "bank", None) is None:
            return EngineSound(audio, None, len(seg))
        arr = np.asarray(seg, dtype=np.int16)
        if arr.ndim == 1:
            arr = np.repeat(arr[:, None], 2, axis=1)
        sid = audio.bank.alloc()
        audio.mixer.load_sound(sid, (arr.astype(np.float32) / 32768.0).tobytes())
        return EngineSound(audio, sid, len(arr))

    @staticmethod
    def from_file(audio, path) -> "EngineSound | None":
        """Load wav/ogg via soundfile (the music banks ship both)."""
        if getattr(audio, "bank", None) is None:
            return None
        import soundfile as sf
        try:
            arr, sr = sf.read(str(path), dtype="float32")
        except Exception as exc:
            print(f"[audio] failed to load {path}: {exc}", file=sys.stderr)
            return None
        if sr != 44100:
            print(f"[audio] {path}: expected 44100 Hz, got {sr} — skipping",
                  file=sys.stderr)
            return None
        if arr.ndim == 1:
            arr = np.stack([arr, arr], axis=1)
        sid = audio.bank.alloc()
        audio.mixer.load_sound(sid, np.ascontiguousarray(arr).tobytes())
        return EngineSound(audio, sid, len(arr))

    def free(self) -> None:
        if self.sid is not None and self.audio.mixer is not None:
            self.audio.mixer.free_sound(self.sid)
            self.sid = None


class EngineChannel:
    """One numbered mixer channel with the pygame idioms music.py uses."""

    __slots__ = ("audio", "idx", "_queued")

    def __init__(self, audio: Audio, idx: int):
        self.audio = audio
        self.idx = idx
        self._queued = None

    def _m(self):
        return getattr(self.audio, "mixer", None)

    def play(self, snd: EngineSound, loops: int = 0) -> None:
        m = self._m()
        if m is None or snd is None or snd.sid is None:
            return
        m.ch_play(self.idx, snd.sid, loops)

    def queue(self, snd: EngineSound) -> None:
        m = self._m()
        if m is None or snd is None or snd.sid is None:
            return
        m.ch_queue(self.idx, snd.sid)

    def get_queue(self):
        """Truthy when a chunk is queued behind the playing one — the
        lanes only ever None-check this."""
        m = self._m()
        if m is None:
            return None
        return True if m.ch_has_queue(self.idx) else None

    def set_volume(self, l: float, r: float | None = None) -> None:
        m = self._m()
        if m is None:
            return
        if r is None:
            r = l
        m.ch_set_volume(self.idx, l, r)

    def stop(self) -> None:
        m = self._m()
        if m is not None:
            m.ch_stop(self.idx)

    def fadeout(self, ms: int) -> None:
        m = self._m()
        if m is not None:
            m.ch_fadeout(self.idx, int(ms))

    def get_busy(self) -> bool:
        m = self._m()
        return bool(m is not None and m.ch_busy(self.idx))
